package com.financetrack.controller;
import com.financetrack.repository.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/reports")public class ReportController{
 private final IncomeRepository income;private final ExpenseRepository expense;private final UserRepository users;public ReportController(IncomeRepository i,ExpenseRepository e,UserRepository u){income=i;expense=e;users=u;}
 @GetMapping public ResponseEntity<?> yearly(@RequestParam(defaultValue="0")int year,@RequestParam(defaultValue="json")String format,Authentication a){int y=year==0?Year.now().getValue():year;Long id=users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId();List<Map<String,Object>> rows=new ArrayList<>();for(int m=1;m<=12;m++){LocalDate from=LocalDate.of(y,m,1),to=from.withDayOfMonth(from.lengthOfMonth());BigDecimal ins=income.findByUserIdAndOccurredOnBetweenOrderByOccurredOnDesc(id,from,to).stream().map(x->x.getAmount()).reduce(BigDecimal.ZERO,BigDecimal::add),outs=expense.total(id,from,to);rows.add(Map.of("month",m,"income",ins,"expenses",outs,"savings",ins.subtract(outs)));}if(format.equalsIgnoreCase("csv")){StringBuilder csv=new StringBuilder("month,income,expenses,savings\n");rows.forEach(r->csv.append(r.get("month")).append(',').append(r.get("income")).append(',').append(r.get("expenses")).append(',').append(r.get("savings")).append('\n'));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=financetrack-"+y+".csv").contentType(MediaType.parseMediaType("text/csv")).body(csv.toString());}return ResponseEntity.ok(Map.of("year",y,"months",rows));}
}
